OA2 = "LE04 OA 02"

# ------------------------------------------------------------------ OA 02
L(OA2, 1,
  "Este cuaderno, lápiz y los textos escritos en cada ejercicio.",
  "Aprenderé a unir lo que dice el texto con lo que ya sé o con lo que he vivido, sin alejarme de lo que el texto cuenta.",
  ["Leo textos cortos y encuentro datos que están escritos.", "Sé que lo que ya conozco puede ayudarme a entender."],
  ["Conectar es unir lo que dice el texto con lo que ya sabes o con algo que has vivido. Si el texto dice que un niño deja su planta junto a la ventana, puedes recordar que las plantas necesitan luz. Esa conexión te ayuda a entender por qué lo hace. Lo que ya sabes antes de leer se llama conocimiento previo.",
   "Hay conexiones que ayudan y conexiones que alejan. Ayudan las que explican algo del texto. Alejan las que cuentan otra historia que no tiene relación. Si piensas en tu cumpleaños mientras lees sobre una planta, te olvidas de lo que importa.",
   "Para conectar bien, haz tres pasos. Primero lee un trozo del texto. Luego pregúntate «¿esto me recuerda algo que sé?». Por último, vuelve al texto y comprueba que lo recordado sirve para entenderlo. Si el texto dice algo distinto de lo que tú pensabas, manda el texto: corrige tu idea."],
  [("conectar", "unir lo que dice el texto con lo que ya sé"), ("conocimiento previo", "lo que ya sé antes de leer"), ("experiencia", "algo que me ha pasado o que he vivido"), ("inferir", "descubrir algo que el texto no dice con todas sus letras, usando pistas")],
  [("Conexión que ayuda", "Texto: «Camila plantó una semilla de girasol en un vaso con tierra y lo puso junto a la ventana». ¿Qué conocimiento ayuda a entender por qué lo puso allí?", ["Me pregunto: ¿por qué junto a la ventana?", "Recuerdo que las plantas necesitan luz para crecer.", "Con eso entiendo la decisión de Camila."], "Que las plantas necesitan luz"),
   ("Conexión que aleja", "En el mismo texto, un niño dice «Me acordé de mi cumpleaños». ¿Esa conexión ayuda a entender el texto?", ["El cumpleaños no tiene relación con la planta.", "No explica nada de lo que hace Camila.", "Es una conexión que aleja."], "No, no ayuda")],
  [("Contar una historia propia larga y olvidar el texto.", "La conexión se vuelve más importante que el texto.", "Usa tu recuerdo solo para entender un detalle y vuelve a leer."), ("Pensar que no sabes nada del tema.", "No se busca en la memoria.", "Pregúntate qué has visto, oído o vivido sobre eso.")],
  ([E("Conectar al leer, ¿es unir el texto con lo que ya sé o copiar el texto en el cuaderno?", "Unir el texto con lo que ya sé", "Conectar significa relacionar lo que se lee con el conocimiento previo."),
    E("Lee: «Tito se puso gorro y bufanda porque hacía frío.» ¿Por qué se abrigó Tito?", "Porque hacía frío", "El propio texto lo dice."),
    E("¿Cuál es un conocimiento previo útil para leer sobre hielo: «El hielo se derrite con el calor» o «El texto tiene tres líneas»?", "«El hielo se derrite con el calor»", "Es algo que se sabe del tema y ayuda a entender lo que se lee.")],
   [E("Texto: «Antes de salir, Lucía miró el cielo gris y metió el paraguas en la mochila.» ¿Qué conocimiento previo explica su decisión?", "Que un cielo gris suele anunciar lluvia", "Con ese conocimiento se entiende por qué lleva paraguas."),
    E("Un niño lee sobre un panadero y piensa en su último paseo al campo. ¿La conexión ayuda o aleja?", "Aleja", "El paseo no explica nada del texto."),
    E("Texto: «El agua del charco amaneció dura y blanca.» Si recuerdas que el agua se congela con mucho frío, ¿qué puedes deducir de la noche?", "Que hizo mucho frío", "Un charco duro y blanco indica que el agua se congeló.")],
   [E("Texto: «Don Raúl guardó las macetas dentro de la casa porque esa noche habría helada.» Si sabes que el frío intenso daña las plantas, ¿para qué las guardó?", "Para protegerlas del frío", "La helada es frío intenso y puede dañar las plantas."),
    E("Un lector dice: «Leí que Ema usa botas de goma y recordé que las botas de goma protegen del agua». ¿Qué debe revisar en el texto para comprobar su conexión?", "Si hay agua o lluvia en el texto", "La conexión sirve si el texto habla de agua o lluvia."),
    E("Texto: «Nico colgó la polera mojada al sol y, en una hora, estaba seca.» ¿Qué conocimiento previo explica que se secara?", "Que el sol y el calor secan lo mojado", "El calor hace que el agua se evapore de la tela.")],
   [E("Un lector lee «El gato se lanzó sobre el cojín y se durmió al sol» y cuenta durante diez minutos su viaje de verano. ¿Qué error cometió al conectar?", "Se alejó del texto", "Su recuerdo no ayuda a entender lo que dice el texto."),
    E("Un niño creía que los peces duermen fuera del agua. El texto dice que los peces duermen dentro del agua. ¿Qué debe hacer con su idea?", "Corregirla según el texto", "Cuando el texto dice algo distinto, se corrige la idea previa.")],
   [E("Texto: «Mara se puso gafas oscuras y una gorra para ir a la playa a mediodía.» Escribe en una frase corta qué conocimiento previo explica lo que hizo.", "Que el sol fuerte molesta a la vista y quema la piel", "Las gafas y la gorra protegen del sol del mediodía."),
    E("Tres lectores conectan con el texto «El panadero se levantó a las cuatro para tener el pan caliente al amanecer». A: «Recordé que el pan se hornea antes de venderlo». B: «Me acordé de mi mascota». C: «Pensé que hornear toma tiempo». ¿Cuántas conexiones ayudan a entender?", "2", "A y C explican por qué se levanta temprano; B no tiene relación.")]),
  [E("Lees: «Rodolfo regó el tomate cada mañana y puso una estaca para sostener el tallo.» Recuerdas que las plantas altas se doblan si no se apoyan. ¿Para qué puso la estaca?", "Para sostener la planta", "Sin apoyo, un tallo largo se dobla.")],
  [E("¿Cómo se llama lo que ya sé antes de leer?", "Conocimiento previo", "Es el nombre de lo que ya sabemos del tema."),
   E("¿Una conexión que cuenta otra historia sin relación con el texto ayuda o aleja?", "Aleja", "No explica nada del texto."),
   E("Después de recordar algo, ¿qué paso falta: volver al texto o dejar de leer?", "Volver al texto", "Hay que comprobar que lo recordado sirve para entender.")],
  ("Lee este texto y escribe dos conexiones que ayuden a entenderlo y una que aleje: «Ema guardó su abrigo en el armario, sacó las sandalias y puso un sombrero de paja sobre la mesa. Mañana empiezan las vacaciones de verano.»", "Ayuda: en verano hace calor, por eso guarda el abrigo. Ayuda: el sombrero de paja protege del sol. Aleja: me acordé de mi tarea de matemática.", ["escribe dos conexiones que explican el texto", "escribe una que no ayuda", "vuelve al texto para comprobarlas"], ["tres frases escritas"], ["conectar con algo que no tiene relación", "olvidar el texto"], "Explica a otra persona cómo cada conexión se relaciona (o no) con lo que dice el texto."),
  "Lee un texto breve de tu libro y escribe una cosa que ya sabías y que te ayudó a entenderlo.",
  "Busca un texto en el que tu conocimiento previo sea distinto de lo que dice, y anota cómo corriges tu idea.")

L(OA2, 2,
  "Este cuaderno, lápiz y los textos escritos en cada ejercicio.",
  "Aprenderé a detectar dónde dejé de entender y a releer ese pedazo con una estrategia, para entender de nuevo.",
  ["Conecto lo que leo con lo que sé.", "Leo oraciones con sentido y ritmo."],
  ["A veces, mientras lees, sientes que algo no calza: no entiendes una palabra, una oración o a quién se refiere el texto. Ese lugar se llama punto de quiebre. Es normal que aparezca. Lo importante es detectarlo y no seguir leyendo como si nada.",
   "Para releer bien, haz esto: primero detente y marca el punto donde dejaste de entender. Luego vuelve un poco antes y lee más despacio. Fíjate en las palabras cercanas, que a veces explican una palabra difícil, y busca el dato que te faltó, por ejemplo cuántos o quién eran. Si hace falta, léelo en voz alta.",
   "Al terminar la relectura, comprueba: ¿ahora puedo decir con mis palabras lo que dice ese trozo? Si todavía no, relee otra vez o escribe una pregunta para resolver después. Releer no es perder tiempo: es lo que hacen los buenos lectores."],
  [("releer", "volver a leer un trozo para entenderlo mejor"), ("punto de quiebre", "lugar donde dejo de entender"), ("pista del contexto", "palabras cercanas que ayudan a entender una palabra difícil"), ("comprobar", "revisar si lo que entendí es correcto")],
  [("Palabra difícil", "Texto: «Los pescadores salieron a las cinco de la mañana. La niebla era tan espesa que apenas se veían las boyas.» ¿Qué significa «espesa»?", ["Es la palabra que no entiendo.", "Releo la oración: «apenas se veían las boyas».", "Si casi no se ve, la niebla es muy densa y cerrada."], "Muy densa, muy cerrada"),
   ("Buscar un dato", "Texto: «Beto tenía dos monedas de $500 y una de $100. Compró un helado de $900.» ¿Cuánto dinero tenía Beto antes de comprar?", ["Releo el dato: dos monedas de $500 y una de $100.", "Sumo: 500 + 500 + 100 = 1.100.", "Respondo con lo que dice el texto."], "$1.100")],
  [("Seguir leyendo sin entender y esperar que más adelante se aclare.", "El problema crece con cada oración.", "Detente, marca el punto y relee desde un poco antes."), ("Releer todo el texto de nuevo, sin mirar el punto exacto.", "No se ubica dónde estaba el problema.", "Relee solo el trozo que no entendiste y el que está justo antes.")],
  ([E("¿Cómo se llama el lugar del texto donde dejo de entender?", "Punto de quiebre", "Es el nombre de ese lugar."),
    E("Si no entiendes una oración, ¿conviene seguir de largo o releerla?", "Releerla", "Releer ayuda a entender lo que se escapó."),
    E("En «La niebla era tan espesa que apenas se veían las boyas», ¿qué dato dice cuánto se veía: «apenas se veían las boyas» o «a las cinco de la mañana»?", "«apenas se veían las boyas»", "Esa parte explica que se veía muy poco.")],
   [E("«Cuando llegó la tormenta, el barco quedó a la deriva, sin rumbo, empujado por las olas.» ¿Qué significa «a la deriva»?", "Llevado por el agua, sin dirección", "Las palabras «sin rumbo, empujado por las olas» dan la pista."),
    E("¿Qué se hace primero al releer: marcar el punto donde dejé de entender o cambiar de libro?", "Marcar el punto donde dejé de entender", "Hay que ubicar el problema antes de resolverlo."),
    E("«Lola guardó los lápices en el estuche. Después lo cerró.» En «lo cerró», ¿qué se cerró: el estuche o los lápices?", "El estuche", "«Cerró» se refiere a lo que se puede cerrar: el estuche.")],
   [arith("Beto tenía dos monedas de $500 y una de $100. Compró un helado de $900. ¿Cuánto dinero le sobró?", "500+500+100-900", "Se suma lo que tenía y se resta lo que gastó."),
    E("Texto: «Marta no pudo abrir el frasco. Era tan hermético que ni con las dos manos se movió la tapa.» ¿Qué significa «hermético»?", "Muy bien cerrado", "La pista es que la tapa no se movió ni con las dos manos."),
    E("«El domingo comimos en casa de la abuela. Allí, ella nos sirvió sopaipillas.» En «ella», ¿a quién se refiere?", "A la abuela", "Es la única persona femenina mencionada que sirve.")],
   [E("Un lector subrayó «apenas» y «espesa» en «La niebla era tan espesa que apenas se veían las boyas» porque no entendió. ¿Qué debe hacer primero: buscar una pista en la misma oración o saltar al final?", "Buscar una pista en la misma oración", "El mismo texto suele explicar la palabra difícil."),
    E("Dos lectores no entienden la palabra «espesa». Uno relee el trozo y el otro sigue. ¿Cuál tiene más posibilidades de entender?", "El que relee", "Releer da la oportunidad de usar las pistas.")],
   [E("Texto: «Pía llegó tarde porque la puerta del bus escolar se trabó. Aun así, la profesora la dejó entrar.» ¿Por qué llegó tarde Pía?", "Porque la puerta del bus se trabó", "El motivo aparece en la primera oración."),
    E("En «Era un camino sinuoso, lleno de curvas», ¿qué palabra da la pista para entender «sinuoso»?", "curvas", "Un camino lleno de curvas es un camino con vueltas, es decir, sinuoso.")]),
  [E("Marcos lee en el manual de su bicicleta: «Infle el neumático hasta la presión que indica su costado». No entiende «neumático». La imagen del manual muestra una rueda. ¿Qué parte de la bicicleta es el neumático?", "La goma de la rueda, que se infla", "La imagen de la rueda es la pista.")],
  [E("¿Qué debo hacer al notar un punto de quiebre?", "Detenerme y releer", "Releer ayuda a recuperar el sentido."),
   E("Una palabra desconocida, ¿puede explicarse con las palabras cercanas?", "Sí", "A eso se le llama pista del contexto."),
   E("Después de releer, ¿qué debo comprobar: si puedo decir el trozo con mis palabras o si el texto es largo?", "Si puedo decirlo con mis palabras", "Esa es la señal de que lo entendí.")],
  ("Lee este texto, marca el punto donde algo cuesta entender y escribe qué hiciste para entenderlo: «Al abrir la caja, Julia encontró una brújula antigua. La aguja temblaba, pero siempre volvía a apuntar hacia el mismo lado. Entonces Julia comprendió cuál era el norte.»", "Me costó entender «la aguja temblaba». Releí la oración y vi que, aunque se movía, siempre volvía al mismo lado. Eso indica el norte.", ["marca un punto de quiebre real del texto", "relee un poco antes", "explica con sus palabras lo que entendió"], ["texto marcado", "explicación escrita"], ["no marcar el punto exacto", "seguir sin releer"], "Cuéntale a otra persona qué parte releíste y qué entendiste al volver a leerla."),
  "Anota en una lista tres palabras que no entendiste en un libro y busca la pista del contexto para cada una.",
  "Escribe un párrafo de tres oraciones con una palabra difícil que se pueda entender por las palabras cercanas.")

L(OA2, 3,
  "Este cuaderno, lápiz y los textos escritos en cada ejercicio. Si quieres, hojas y colores para dibujar.",
  "Aprenderé a imaginar imágenes mentales con lo que describe el texto, usando solo detalles que el texto entrega.",
  ["Releo para entender.", "Distingo lo que dice el texto de lo que yo imagino."],
  ["Visualizar es formar una imagen en la mente con lo que dice el texto. Funciona como una película interior: ves colores, formas, lugares, cantidades y también puedes imaginar sonidos y olores. Visualizar ayuda a comprender y a recordar.",
   "Para visualizar bien, busca en el texto los detalles comprobables: colores, números, tamaños, posiciones («a la izquierda», «bajo el árbol»). Son detalles que puedes mostrar con una oración del texto. Lo que no dice el texto es una invención tuya: puedes agregarlo a tu imagen, pero no debes tratarlo como dato del texto.",
   "Una forma de comprobar tu imagen es dibujar un esquema o decirlo en voz alta y volver al texto. Si el dibujo tiene algo que el texto no dice o le falta algo que sí dice, ajusta la imagen. Lo que importa es que la imagen sea fiel al texto."],
  [("visualizar", "formar una imagen en la mente a partir del texto"), ("detalle comprobable", "dato que se puede mostrar con una oración del texto"), ("posición", "lugar donde está algo: a la izquierda, bajo, junto a"), ("invención", "algo que agrego yo y el texto no dice")],
  [("Buscar detalles comprobables", "Texto: «En el patio hay un aromo con flores amarillas. A su izquierda hay dos bancas verdes.» ¿Cuántas bancas hay y de qué color?", ["Busco el número: dos.", "Busco el color: verdes.", "Reúno ambos datos."], "Dos bancas verdes"),
   ("Separar texto e invención", "En el mismo texto, un niño imagina que en las bancas hay una mochila roja. ¿Es un dato del texto?", ["Busco «mochila» en el texto: no aparece.", "Entonces es algo que imaginó él.", "Puede estar en su imagen, pero no es dato del texto."], "No, es invención")],
  [("Dibujar detalles que el texto no menciona y decir que el texto los dice.", "Se mezcla lo imaginado con lo leído.", "Marca en el texto la frase que prueba cada detalle."), ("Imaginar solo un detalle y olvidar los demás.", "Se lee sin fijarse en todos los datos.", "Haz una lista de colores, números y posiciones antes de dibujar.")],
  ([E("Visualizar, ¿es formar una imagen mental del texto o aprender el texto de memoria?", "Formar una imagen mental del texto", "Visualizar es imaginar lo que describe el texto."),
    E("Texto: «Sobre la mesa hay tres manzanas rojas.» ¿Cuántas manzanas hay?", "3", "El texto dice tres."),
    E("En el mismo texto, ¿de qué color son las manzanas?", "Rojas", "El texto dice «rojas».")],
   [E("Texto: «A la derecha del aromo hay un bebedero de metal.» ¿Qué hay a la derecha del aromo?", "Un bebedero de metal", "La posición «a la derecha» la dice el texto."),
    E("Texto: «Una gaviota blanca descansa sobre el techo del bote azul.» ¿Dónde está la gaviota?", "Sobre el techo del bote", "La posición la indica «sobre el techo del bote»."),
    E("Texto: «Una gaviota blanca descansa sobre el techo del bote azul.» ¿Cuál es un dato del texto: «el bote es azul» o «el bote es nuevo»?", "«El bote es azul»", "El texto no dice nada sobre si es nuevo.")],
   [E("«En el patio hay un aromo con flores amarillas. A su izquierda hay dos bancas verdes. Bajo el árbol, tres niños arman una torre con piedras.» ¿Cuántos niños hay y dónde están?", "Tres, bajo el árbol", "Número y posición salen del texto."),
    E("Texto: «Bajo el árbol, tres niños arman una torre con piedras.» ¿Se puede saber de qué color es la ropa de los niños?", "No", "El texto no da ese dato."),
    arith("En el patio hay 2 bancas verdes y 3 niños bajo el árbol. Si cada niño se sienta en una banca distinta, ¿cuántos niños se quedan sin banca? (hay 2 bancas)", "3-2", "Se restan las bancas disponibles de los niños.")],
   [E("Texto: «En el patio hay un aromo con flores amarillas.» Un niño dibuja el aromo con flores rojas. ¿Qué dice el texto que corrige su dibujo?", "Las flores son amarillas", "El texto da el color de las flores."),
    E("Texto: «Una gaviota blanca descansa sobre el techo del bote azul.» Dos lectores visualizan la escena. Uno dibuja la gaviota en el agua y el otro sobre el techo del bote. ¿Quién fue fiel al texto?", "El segundo", "El texto ubica la gaviota sobre el techo.")],
   [E("Texto: «Junto a la puerta hay dos botas de goma amarillas y un paraguas verde.» Si dibujas todo lo que dice el texto, ¿cuántos objetos dibujas?", "3", "Dos botas y un paraguas suman tres objetos.", "2+1"),
    E("Texto: «En la ventana, la luna llena iluminaba tres macetas con helechos.» ¿Cuál NO es un dato del texto: «hay tres macetas» o «las macetas son de barro»?", "«las macetas son de barro»", "El material de las macetas no aparece en el texto.")]),
  [E("Debes dibujar la sala descrita así: «Al fondo hay una pizarra verde. Entre la pizarra y las cuatro mesas hay una alfombra roja.» ¿Qué dibujas entre la pizarra y las mesas?", "Una alfombra roja", "El texto ubica la alfombra entre la pizarra y las mesas.")],
  [E("¿Cómo se llama el dato que se puede mostrar con una oración del texto?", "Detalle comprobable", "Se puede mostrar con el texto."),
   E("Si agregas algo que el texto no dice, ¿es un dato del texto o una invención?", "Una invención", "El texto no lo contiene."),
   E("Para comprobar tu imagen, ¿vuelves al texto o la cambias al azar?", "Vuelvo al texto", "Se compara la imagen con lo que dice.")],
  ("Lee el texto y haz un dibujo simple que muestre solo lo que dice. Después subraya la frase que prueba cada detalle: «En la plaza del pueblo hay una fuente de piedra. A su izquierda, un quiosco rojo. A su derecha, dos bancas de madera. Sobre la fuente, tres palomas.»", "Dibujé la fuente al centro, el quiosco rojo a la izquierda, dos bancas a la derecha y tres palomas sobre la fuente. No dibujé personas porque el texto no las menciona.", ["dibuja los cuatro elementos con sus posiciones", "usa los colores y números del texto", "no agrega detalles como si fueran del texto"], ["dibujo", "frases subrayadas"], ["dibujar más cosas de las que dice el texto", "cambiar un color o un número"], "Muestra tu dibujo y explica la frase del texto que apoya cada elemento."),
  "Lee una descripción de tu libro y dibuja el lugar, anotando la frase que prueba cada detalle.",
  "Escribe una descripción de 4 oraciones con números, colores y posiciones, y pide a alguien que la dibuje.")

L(OA2, 4,
  "Este cuaderno, lápiz y los textos escritos en cada ejercicio.",
  "Aprenderé a recapitular: decir con mis palabras lo que pasó o lo que dice cada parte del texto, antes de seguir leyendo.",
  ["Releo cuando no entiendo.", "Distingo la idea principal de un detalle."],
  ["Recapitular es detenerse y decir con tus palabras lo más importante de lo que acabas de leer. No se trata de repetir el texto, sino de resumirlo: cuentas qué pasó o qué dice el trozo en una o dos oraciones. Sirve para comprobar si entendiste y para no perder el hilo.",
   "Los textos largos se recapitulan por segmentos. Un segmento es un trozo del texto, por ejemplo un párrafo. Al terminar cada segmento, haces una pausa y te preguntas: ¿quién?, ¿qué pasó?, ¿qué es lo importante? Después de recapitular todos los segmentos, puedes unir las recapitulaciones y obtener un resumen del texto completo.",
   "Una buena recapitulación es breve, dice solo lo importante y mantiene el orden del texto. No agrega opiniones ni detalles que no están. Si te resulta difícil recapitular un segmento, vuelve a leerlo."],
  [("recapitular", "decir con mis palabras lo más importante de lo leído"), ("segmento", "trozo de un texto, por ejemplo un párrafo"), ("resumen", "texto breve con lo más importante"), ("idea principal", "lo más importante que dice un trozo")],
  [("Recapitular un segmento", "Segmento: «El domingo, Inés y su abuelo fueron a la feria. Compraron zapallos, choclos y un queso fresco, y volvieron a casa cargados de bolsas.» ¿Cómo lo recapitulas?", ["Pregunto: ¿quiénes? Inés y su abuelo.", "¿Qué pasó? Fueron a la feria y compraron alimentos.", "Lo resumo en una oración."], "Inés y su abuelo fueron a la feria y compraron alimentos"),
   ("Elegir la mejor recapitulación", "Segmento: «Al llegar a casa, prepararon una cazuela con los zapallos y los choclos. La abuela la probó y dijo que estaba lista.» Opciones: (a) Hicieron una cazuela. (b) A la abuela le gusta cocinar mucho y sabe de todo. ¿Cuál recapitula mejor?", ["La opción (a) dice lo que pasó.", "La opción (b) agrega cosas que el texto no dice.", "Elijo la que se queda en el texto."], "(a)")],
  [("Copiar el texto entero con otras palabras.", "Se cree que recapitular es repetir.", "Dilo con una o dos oraciones cortas."), ("Agregar opiniones («qué lindo cuento»).", "Se mezcla opinión con resumen.", "Cuenta solo lo que pasó o lo que dice el texto.")],
  ([E("Recapitular, ¿es decir con mis palabras lo más importante o copiar el texto?", "Decir con mis palabras lo más importante", "Es un resumen propio, no una copia."),
    E("Un trozo de texto, como un párrafo, ¿se llama segmento o título?", "Segmento", "Segmento es cada parte en que se divide un texto."),
    E("Una buena recapitulación, ¿es larga o breve?", "Breve", "Dice solo lo importante.")],
   [E("«El domingo, Inés y su abuelo fueron a la feria. Compraron zapallos, choclos y un queso fresco.» ¿Quiénes fueron a la feria?", "Inés y su abuelo", "Lo dice la primera oración."),
    E("Texto: «Inés y su abuelo fueron a la feria y compraron zapallos, choclos y un queso fresco.» ¿Cuál recapitula bien: «Fueron a la feria y compraron alimentos» o «Fueron al cine»?", "«Fueron a la feria y compraron alimentos»", "La otra opción cambia lo que dice el texto."),
    E("¿Cuándo se recapitula en un texto largo: al terminar cada segmento o solo al principio?", "Al terminar cada segmento", "Así se comprueba si se entendió cada parte.")],
   [E("Texto en tres segmentos: 1) «Tomás perdió su gorra en el cerro.» 2) «La buscó con su hermana por una hora, pero no la encontró.» 3) «Al día siguiente, un vecino la devolvió con una nota.» ¿Cuántas recapitulaciones se necesitan si se resume cada segmento?", "3", "Se hace una por segmento."),
    E("Recapitula en una oración el segmento 2: ¿«Buscaron la gorra sin éxito» o «Tomás ganó un premio»?", "«Buscaron la gorra sin éxito»", "Resume lo que dice el segmento 2."),
    E("¿Qué segmento recapitula esta oración: «Un vecino la devolvió»?", "El segmento 3", "El vecino aparece en el último segmento.")],
   [E("Una recapitulación dice: «Tomás perdió su gorra y fue muy tonto». ¿Qué parte no corresponde a un resumen?", "«fue muy tonto»", "Es una opinión que el texto no dice."),
    E("Un lector resume los tres segmentos en el orden 3, 1, 2. ¿Mantiene el orden del texto?", "No", "El orden del texto es 1, 2, 3.")],
   [E("Segmentos: A) «Lía armó una caja de cartón con tapa.» B) «Dentro puso hojas secas y pequeñas ramas.» C) «Ahí dejó a su caracol para que descansara.» Une las tres recapitulaciones en un resumen. ¿Cuál es correcto: «Lía armó una caja con hojas y ramas para su caracol» o «Lía compró una pecera»?", "«Lía armó una caja con hojas y ramas para su caracol»", "Resume los tres segmentos en el orden del texto."),
    E("Si cada segmento tiene 30 palabras y el texto tiene 3 segmentos, ¿cuántas palabras tiene el texto completo?", "90", "Se suman tres veces 30.", "30+30+30")]),
  [E("Debes contarle a tu curso un cuento de dos párrafos sin leerlo. Después del primer párrafo recapitulas en una frase y después del segundo en otra. ¿Cuántas frases dijiste en total?", "2", "Una por cada párrafo.")],
  [E("¿Cómo se llama el texto breve con lo más importante?", "Resumen", "Es la unión de las recapitulaciones."),
   E("Un resumen, ¿lleva opiniones o solo lo importante?", "Solo lo importante", "La opinión no forma parte del resumen."),
   E("Si no puedes recapitular un segmento, ¿qué haces?", "Vuelvo a leerlo", "Releer ayuda a entender.")],
  ("Lee este texto en tres segmentos y escribe una oración que recapitule cada uno. Luego únelas en un resumen de tres oraciones. 1) «Elena encontró un pajarito en el patio. Tenía un ala torcida y no podía volar.» 2) «Llamó a su papá, y juntos lo pusieron en una caja con trapos suaves y agua.» 3) «Al día siguiente, una veterinaria lo revisó y dijo que se recuperaría en unas semanas.»", "1) Elena encontró un pajarito herido. 2) Lo cuidaron en una caja con agua. 3) Una veterinaria dijo que se recuperaría. Resumen: Elena encontró un pajarito herido, lo cuidó en una caja y una veterinaria dijo que sanaría.", ["resume cada segmento en una oración", "mantiene el orden", "no agrega opiniones"], ["tres oraciones", "resumen unido"], ["copiar el texto", "agregar opiniones"], "Lee tu resumen a otra persona y pregúntale si entendió qué pasó en el cuento."),
  "Lee dos párrafos de tu libro y cuéntaselos a alguien sin mirar, diciendo lo más importante de cada uno.",
  "Recapitula un capítulo de un libro en tres oraciones, una por cada parte importante.")

L(OA2, 5,
  "Este cuaderno, lápiz y los textos escritos en cada ejercicio.",
  "Aprenderé a formular preguntas sobre lo que leo y a responderlas buscando en el texto o razonando con pistas.",
  ["Recapitulo lo leído.", "Reconozco palabras como quién, qué, dónde y por qué."],
  ["Preguntarte cosas mientras lees te ayuda a entender mejor. Hay preguntas cuya respuesta está escrita en el texto, como «¿quién llegó?» o «¿cuántos eran?». Se llaman preguntas de respuesta explícita y se responden encontrando la oración del texto.",
   "Hay otras preguntas cuya respuesta no está escrita, pero se puede deducir con pistas: «¿por qué estaba triste?». Son preguntas de inferencia. Se responden uniendo pistas del texto con lo que ya sabes. Una buena respuesta siempre se apoya en algo del texto.",
   "Para formular buenas preguntas, usa palabras como ¿quién?, ¿qué?, ¿cuándo?, ¿dónde?, ¿cuánto? y ¿por qué?. Antes de seguir, intenta responder tus propias preguntas. Si no puedes, relee el texto."],
  [("pregunta explícita", "pregunta cuya respuesta está escrita en el texto"), ("pregunta de inferencia", "pregunta cuya respuesta se deduce con pistas"), ("pista", "dato del texto que ayuda a deducir algo"), ("formular", "escribir o decir una pregunta o una idea")],
  [("Responder una pregunta explícita", "Texto: «Rodrigo llegó a la escuela a las ocho. Traía una caja con semillas de lupino.» Pregunta: ¿qué traía Rodrigo?", ["Busco la palabra «traía».", "Leo lo que sigue: una caja con semillas de lupino.", "Respondo con ese dato."], "Una caja con semillas de lupino"),
   ("Responder una pregunta de inferencia", "Texto: «Pía abrazó fuerte a su perro y no quiso soltarlo cuando el auto se detuvo frente al veterinario.» ¿Cómo se siente Pía?", ["El texto no dice cómo se siente.", "Pistas: abraza fuerte, no quiere soltarlo, veterinario.", "Eso indica que está preocupada."], "Preocupada o asustada")],
  [("Responder con lo que se me ocurre sin mirar el texto.", "No se buscan las pistas.", "Busca una oración del texto que apoye tu respuesta."), ("Preguntar cosas que el texto no puede responder («¿qué comió el autor ayer?»).", "No se piensa en el texto.", "Haz preguntas que el texto o sus pistas permitan responder.")],
  ([E("«¿Quién llegó a la escuela?» ¿Es pregunta de respuesta explícita o de inferencia, si el texto dice «Rodrigo llegó a la escuela»?", "Explícita", "La respuesta está escrita en el texto."),
    E("¿Qué palabra interrogativa sirve para preguntar el motivo: «por qué» o «cuántos»?", "Por qué", "«Por qué» pregunta la causa."),
    E("Para responder una pregunta explícita, ¿se busca en el texto o solo se imagina?", "Se busca en el texto", "La respuesta está escrita.")],
   [E("Texto: «Rodrigo llegó a la escuela a las ocho con una caja de semillas de lupino.» ¿A qué hora llegó?", "A las ocho", "La hora está escrita en el texto."),
    E("¿Qué palabra interrogativa usas para preguntar por un lugar: «dónde» o «quién»?", "Dónde", "«Dónde» pregunta por el lugar."),
    E("Texto: «Rita buscó su abrigo y salió tiritando.» ¿Cuántas pistas de frío hay: buscar el abrigo y tiritar?", "2", "Buscar un abrigo y tiritar son dos pistas de que hacía frío.")],
   [E("Texto: «Pía abrazó fuerte a su perro y no quiso soltarlo cuando el auto se detuvo frente al veterinario.» ¿Cuál es una pregunta de inferencia: «¿Qué hizo Pía?» o «¿Por qué Pía no quería soltarlo?»", "«¿Por qué Pía no quería soltarlo?»", "Su respuesta no está escrita y se deduce con pistas."),
    E("Texto: «Pía abrazó fuerte a su perro y no quiso soltarlo cuando el auto se detuvo frente al veterinario.» ¿Dónde estaban Pía y su perro al final: frente al veterinario o en el parque?", "Frente al veterinario", "Lo dice la última parte del texto."),
    E("Texto: «Pía abrazó fuerte a su perro y no quiso soltarlo cuando el auto se detuvo frente al veterinario.» Un lector responde «Pía está contenta». ¿Qué pista contradice su respuesta?", "Abraza fuerte a su perro y no quiere soltarlo", "Esas acciones muestran preocupación, no alegría.")],
   [E("Texto: «Las ventanas estaban empañadas y el olor a pan recién horneado llegaba a todo el barrio.» ¿Cuál pregunta se responde con una inferencia: «¿Qué olor llegaba al barrio?» o «¿Por qué se empañaron las ventanas?»", "«¿Por qué se empañaron las ventanas?»", "No está escrito: se deduce del calor del horno y el aire de afuera."),
    E("Dos lectores responden «¿por qué estaba mojado el piso?». Uno dice «porque llovió» y el otro «porque sí». ¿Cuál se apoya en el texto si el texto dice «Entró con el paraguas goteando»?", "El primero", "El paraguas goteando es una pista de lluvia.")],
   [E("Texto: «Mateo guardó su cuaderno, tomó su mochila y fue el último en salir de la sala. Apagó la luz.» Si preguntas «¿por qué apagó la luz?», ¿qué pista del texto usas?", "Que fue el último en salir", "Quien sale último apaga la luz."),
    E("Lees un texto de 4 párrafos y formulas 2 preguntas por párrafo. ¿Cuántas preguntas formulaste?", "8", "Son 4 veces 2.", "4+4")]),
  [E("En la biblioteca lees: «La bibliotecaria dijo que los libros nuevos llegarían el jueves». Tu compañero pregunta «¿cuándo llegarán los libros?». ¿Es explícita o de inferencia?", "Explícita", "La respuesta, el jueves, está escrita.")],
  [E("¿Cómo se llama una pregunta cuya respuesta está escrita en el texto?", "Pregunta explícita", "Se responde buscando en el texto."),
   E("¿Qué se necesita para responder una pregunta de inferencia: pistas del texto o ninguna?", "Pistas del texto", "La respuesta se deduce con pistas."),
   E("¿Con qué palabra preguntas la causa de algo?", "Por qué", "«Por qué» pregunta el motivo.")],
  ("Lee este texto, escribe dos preguntas explícitas y dos de inferencia, y respóndelas con una frase del texto: «Fernanda llegó corriendo al paradero. El bus ya se alejaba. Respiró hondo, miró su reloj y sacó su cuaderno para esperar el siguiente.»", "Explícita: ¿Adónde llegó corriendo Fernanda? Al paradero. Explícita: ¿Qué sacó? Su cuaderno. Inferencia: ¿Por qué corría? Para alcanzar el bus. Inferencia: ¿Qué hará ahora? Esperar el siguiente.", ["formula dos preguntas explícitas", "formula dos de inferencia", "apoya cada respuesta en el texto"], ["cuatro preguntas con respuesta"], ["preguntas que el texto no permite responder", "respuestas sin pistas"], "Intercambia tus preguntas con otra persona y comprueba si puede responderlas con el texto."),
  "Después de leer un capítulo de tu libro, escribe tres preguntas y respóndelas.",
  "Escribe tres preguntas de inferencia sobre un cuento y explica qué pista usas para cada una.")

L(OA2, 6,
  "Este cuaderno, lápiz y los textos escritos en cada ejercicio.",
  "Aprenderé a subrayar solo lo importante para responder una pregunta o estudiar, y a no subrayar todo.",
  ["Recapitulo y formulo preguntas.", "Reconozco la idea principal de un párrafo."],
  ["Subrayar es marcar con una línea las palabras o frases más importantes de un texto. Sirve para volver rápido a lo esencial sin leer todo de nuevo. Pero si subrayas casi todo, ya no se distingue lo importante.",
   "Antes de subrayar, pregúntate para qué lees. Si buscas «cuándo se riega una planta», subrayas solo el dato del riego. Subraya palabras clave: nombres, números, fechas, definiciones. No necesitas subrayar oraciones completas ni adornos del texto.",
   "Un buen subrayado es corto. Después de subrayar, comprueba: si solo leyera lo subrayado, ¿entendería la idea principal y podría contestar mi pregunta? Si falta algo, agrégalo; si sobra, no lo subrayes. Se subraya con lápiz y, si el libro no es tuyo, en una hoja aparte."],
  [("subrayar", "marcar con una línea lo importante de un texto"), ("palabra clave", "palabra imprescindible para entender una idea"), ("relevante", "importante para el propósito de la lectura"), ("propósito", "para qué leo un texto")],
  [("Subrayar según la pregunta", "Texto: «El helecho de Lía vive junto a la ventana, donde recibe luz suave. Se riega dos veces por semana, por la mañana. Su maceta es azul.» Pregunta: ¿cuántas veces se riega? ¿Qué subrayas?", ["La pregunta pide una cantidad de riegos.", "Busco el dato: «dos veces por semana».", "El color de la maceta no responde la pregunta."], "«dos veces por semana»"),
   ("Revisar un subrayado", "Una niña subrayó las cuatro oraciones de un párrafo de cuatro oraciones. ¿Está bien subrayado?", ["Subrayó todo.", "Entonces no se distingue lo importante.", "Debe elegir solo las palabras clave."], "No, subrayó demasiado")],
  [("Subrayar el párrafo completo.", "Todo parece importante.", "Elige solo nombres, números, fechas y definiciones."), ("Subrayar sin saber para qué.", "No se piensa en la pregunta.", "Primero lee la pregunta o el propósito.")],
  ([E("Subrayar, ¿es marcar lo importante o marcar todo?", "Marcar lo importante", "Un subrayado útil destaca lo esencial."),
    E("Antes de subrayar, ¿qué conviene saber: el propósito de la lectura o el número de páginas?", "El propósito de la lectura", "El propósito indica qué es importante."),
    E("Si subrayas todo el párrafo, ¿se distingue lo importante?", "No", "Todo queda igual de marcado.")],
   [E("Texto: «El helecho de Lía vive junto a la ventana. Se riega dos veces por semana. Su maceta es azul.» Si te preguntan cuántas veces se riega, ¿qué subrayas?", "dos veces por semana", "Responde directamente la pregunta."),
    E("En ese texto, ¿es relevante el color de la maceta para saber cuándo se riega?", "No", "El color no cambia el riego."),
    E("Una palabra clave, ¿es imprescindible para entender la idea o decorativa?", "Imprescindible", "Sin ella se pierde la idea.")],
   [E("Texto: «El huerto de la escuela queda detrás del gimnasio. Se riega los martes y los viernes. Tiene una carretilla roja.» Si te piden subrayar dónde queda, ¿qué subrayas?", "queda detrás del gimnasio", "Responde la pregunta por el lugar."),
    E("Texto: «La biblioteca abre de lunes a viernes. Los sábados cierra. Tiene seis mesas azules.» Para saber si abre el sábado, ¿qué frase subrayas?", "Los sábados cierra", "Responde la pregunta sobre el sábado."),
    E("Un lector subrayó 12 palabras clave en un párrafo de 40 palabras. ¿Cuántas palabras dejó sin subrayar?", "28", "Se resta lo subrayado del total.", "40-12")],
   [E("Una niña subrayó el nombre «Lía», el número «dos» y «veces por semana». ¿Subrayó palabras clave o decoraciones?", "Palabras clave", "Nombre y cantidades sirven para recordar la idea."),
    E("Dos lectores buscan el día en que abre la biblioteca. Uno subraya «lunes a viernes» y otro «seis mesas azules». ¿Quién subrayó lo relevante?", "El primero", "Los días responden la pregunta.")],
   [E("Texto: «El panadero amasa a las cuatro. A las seis hornea. A las ocho abre la tienda.» Si te preguntan a qué hora hornea, ¿qué hora subrayas?", "Las seis", "El texto dice que hornea a las seis."),
    E("Si el panadero amasa a las cuatro y hornea a las seis, ¿cuántas horas pasan entre ambos momentos?", "2", "De las 4 a las 6 hay dos horas.", "6-4")]),
  [E("Estudias una frase del manual de tu bicicleta: «El casco debe ajustarse bajo la barbilla. El color de la correa es negro.» Si te preguntan cómo se usa el casco, ¿subrayas «ajustarse bajo la barbilla» o «es negro»?", "«ajustarse bajo la barbilla»", "Responde cómo se usa el casco; el color no.")],
  [E("¿Cómo se llama la palabra imprescindible para entender una idea?", "Palabra clave", "Es la que sostiene la idea."),
   E("¿Cuándo es relevante un dato: cuando ayuda a mi propósito o cuando es raro?", "Cuando ayuda a mi propósito", "Relevante significa importante para lo que busco."),
   E("¿Se subraya con lápiz en tu cuaderno o con tinta en un libro prestado?", "Con lápiz en mi cuaderno", "En libros que no son tuyos no se marca el texto.")],
  ("Lee el texto y subraya solo lo necesario para responder: ¿qué come la lechuza y cuándo sale? «La lechuza es un ave nocturna. Sale de noche a cazar ratones. De día descansa en un hueco. Tiene plumas claras.» Luego escribe tu respuesta.", "Subrayé «sale de noche» y «cazar ratones». Respuesta: la lechuza come ratones y sale de noche.", ["subraya solo lo relevante", "no subraya el color de las plumas", "responde con lo subrayado"], ["texto subrayado", "respuesta escrita"], ["subrayar todo", "subrayar datos que no responden"], "Comprueba si solo con lo subrayado alguien podría responder la pregunta."),
  "Subraya con lápiz, en una fotocopia o copia de un texto, solo las palabras clave de un párrafo.",
  "Elige un párrafo, subraya lo esencial y escribe un resumen de dos oraciones usando solo lo subrayado.")
